recipes.code:
{
  "inputs": [
    {
      "id": "proofslip-api-key",
      "type": "promptString",
      "description": "Your ProofSlip API key (get one free at proofslip.ai)",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@proofslip/mcp-server@0.2.3"
      ],
      "env": {
        "PROOFSLIP_API_KEY": "${input:proofslip-api-key}",
        "PROOFSLIP_BASE_URL": "https://proofslip.ai"
      }
    }
  }
}
